import * as T from 'three';
import {uid,makePart} from './model.js';
import {JOINT_TYPES,jointAxes,createJoint,bodyMatrix,coupledValues,driven,evaluatePose} from './motion.js';
import {captureHarness,insertHarness,harnessCSV,routeLength,normalizeHarnessTemplate} from './harness.js';
import {readRecord,saveRecord} from './storage.js';
import {interfaceDefinitions} from './components.js';
import {panels} from './geometry.js';
import {normalizeFeature,featureDefaults} from './schema.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
export function initEngineering(api){
 const {esc,notify,openModal,download}=api,P=api.project,S=api.studio;let frame=0,preview={},playing=false,harnessLibrary=[];
 const options=(list,current)=>list.map(([k,n])=>`<option value="${esc(k)}"${k===current?' selected':''}>${esc(n)}</option>`).join('');
 const input=(label,name,value,type='text')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}"${type==='number'?' step="any"':''}></label>`;
 const choose=(label,name,list,current)=>`<label>${esc(label)}<select name="${name}">${options(list,current)}</select></label>`;
 const triplet=(label,name,a)=>`<h3>${esc(label)}</h3><div class="fields">${a.map((x,i)=>input(['X','Y','Z'][i],name+i,+x.toFixed(4),'number')).join('')}</div>`;
 const get=(name)=>$(`[name="${name}"]`).value;
 const val=name=>{const raw=get(name);if(!raw.trim()||!Number.isFinite(+raw))throw Error('Enter a number for '+name);return +raw;};
 const coords=name=>[0,1,2].map(i=>val(name+i));
 const run=fn=>{try{return fn();}catch(e){notify(e.message);const error=$('#engineeringError');if(error)error.textContent=e.message;}};
 function form(title,html,fn){stop();openModal(title,`<form id="engineeringForm">${html}<p id="engineeringError" class="form-error" role="alert"></p><div class="modal-actions"><button class="primary" type="submit">Apply</button><button type="button" id="engineeringCancel">Cancel</button></div></form>`);$('#engineeringCancel').onclick=()=>$('#modal').close();$('#engineeringForm').onsubmit=e=>{e.preventDefault();run(()=>{const result=fn();if(result instanceof Promise)result.then(()=>$('#modal').close()).catch(e=>notify(e.message));else if(result!==false)$('#modal').close();});};}
 const bodies=()=>[...P().groups.map(g=>[g.id,'Assembly / '+g.name]),...P().parts.filter(p=>p.kind!=='space').map(p=>[p.id,p.name]),...panels(P().enclosure).map(p=>[p.id,'Enclosure / '+p.name])];
 function stop(restore=true){if(frame)cancelAnimationFrame(frame);frame=0;playing=false;if(restore){preview={};S()?.applyPose?.({});}const button=$('#motionPlay');if(button)button.textContent='Play';}
 function jointForm(existing){
  const child=existing?.child||(bodies().some(([id])=>id===api.selected())?api.selected():bodies()[0]?.[0]);if(!child)return notify('Add a component first.');const j=existing||createJoint(P(),{child});const pivot=new T.Vector3(...j.pivot).applyMatrix4(bodyMatrix(P(),j.parent)).toArray(),axis=new T.Vector3(...j.axis).transformDirection(bodyMatrix(P(),j.parent)).toArray();
  form(existing?'Edit joint':'Add joint',`${input('Name','jointName',j.name)}<div class="fields two">${choose('Joint type','jointType',Object.entries(JOINT_TYPES),j.type)}${input('Screw lead (mm / revolution)','lead',j.lead,'number')}</div><div class="fields two">${choose('Fixed / parent body','parent',[['','World'],...bodies()],j.parent)}${choose('Moving body','child',bodies(),j.child)}</div><p class="fine">The placed geometry defines zero. Parts in a moving subassembly travel together. Use separate groups for each link of a mechanism.</p>${triplet('Pivot in world coordinates (mm)','pivot',pivot)}<button type="button" id="jointCenter">Use moving body center</button>${triplet('Axis in world coordinates','axis',axis)}<p class="fine">Use 1,0,0 for X; 0,1,0 for Y; 0,0,1 for Z. Ball angles use the parent X/Y/Z axes. Planar U is the projected parent X axis (Y when parallel to X).</p><h3>Motion limits</h3>${j.limits.map((a,i)=>`<div class="joint-limit" data-limit="${i}"><strong></strong><div class="fields two">${input('Minimum','min'+i,a.min,'number')}${input('Maximum','max'+i,a.max,'number')}</div></div>`).join('')}`,()=>{
   const type=get('jointType'),next=createJoint(P(),{id:j.id,name:get('jointName'),type,parent:get('parent'),child:get('child'),pivot:coords('pivot'),axis:coords('axis'),lead:val('lead'),limits:[0,1,2].map(i=>({min:val('min'+i),max:val('max'+i)})),values:existing&&existing.type===type?[...existing.values]:[0,0,0]});
   api.commit(()=>{P().joints=P().joints.filter(a=>a.id!==next.id);P().joints.push(next);});dock(next.id);
  });
  function labels(){const list=jointAxes(get('jointType'));$$('[data-limit]').forEach((el,i)=>{el.hidden=i>=list.length;el.querySelector('strong').textContent=list[i]||'';});$('[name=lead]').parentElement.hidden=get('jointType')!=='screw';}labels();$('[name=jointType]').onchange=labels;$('#jointCenter').onclick=()=>{const a=new T.Vector3().setFromMatrixPosition(bodyMatrix(P(),get('child'))).toArray();a.forEach((n,i)=>$(`[name=pivot${i}]`).value=+n.toFixed(4));};$('[name=child]').onchange=()=>$('#jointCenter').click();
 }
 function couplingForm(existing){const list=P().joints.map(j=>[j.id,j.name]);if(list.length<2)return notify('Create at least two joints first.');const c=existing||{id:uid(),name:'Motion link',type:'gear',driver:list[0][0],follower:list[1][0],ratio:-1,pitchDiameter:20,offset:0};form('Link joint motion',`${input('Name','couplingName',c.name)}${choose('Link type','couplingType',[['gear','Gear / rotary ratio'],['rack','Rack and pinion']],c.type)}<div class="fields two">${choose('Driver joint','driver',list,c.driver)}${choose('Follower joint','follower',list,c.follower)}</div><div class="fields">${input('Signed ratio','ratio',c.ratio,'number')}${input('Pinion pitch diameter (mm)','pitchDiameter',c.pitchDiameter,'number')}${input('Follower offset (° or mm)','offset',c.offset,'number')}</div><p>Gear ratio = −driver teeth ÷ follower teeth for external gears. Rack travel = driver angle ÷ 360 × π × pitch diameter × signed ratio. Use ±1 for a direct rack drive. Limits apply to both joints.</p>`,()=>api.commit(()=>{P().couplings=P().couplings.filter(a=>a.id!==c.id);P().couplings.push({...c,name:get('couplingName'),type:get('couplingType'),driver:get('driver'),follower:get('follower'),ratio:val('ratio'),pitchDiameter:val('pitchDiameter'),offset:val('offset')});}));}
 function motionDialog(){stop();openModal('Joints and motion',`<p>Choose a fixed body and a moving part or subassembly, set the pivot and limits, then scrub or play its movement.</p><div class="modal-actions"><button id="addJoint" class="primary">Add joint</button><button id="addCoupling">Link gears / rack</button><button id="motionExample">Add rack-and-pinion example</button></div>${P().joints.length?'':'<p class="muted">No joints yet. Try the example or add a joint to your selected part.</p>'}${P().joints.map(j=>`<div class="feature-row"><button data-joint-control="${esc(j.id)}">${esc(j.name)}<small>${esc(JOINT_TYPES[j.type])} · ${j.values.map(x=>+x.toFixed(2)).join(', ')}</small></button><button data-joint-edit="${esc(j.id)}">Edit</button><button data-joint-delete="${esc(j.id)}" aria-label="Delete ${esc(j.name)}">×</button></div>`).join('')}<h3>Motion links</h3>${P().couplings.map(c=>`<div class="feature-row"><button data-coupling-edit="${esc(c.id)}">${esc(c.name)}<small>${esc(c.type)} · ratio ${c.ratio}</small></button><button data-coupling-delete="${esc(c.id)}" aria-label="Delete link">×</button></div>`).join('')}<p class="fine">Kinematic preview with entered constraints. Forces, backlash, collisions and cable bend/stretch are not simulated. World-anchored joints stay project-specific; internal joints travel with saved subassemblies.</p>`);
  $('#addJoint').onclick=()=>jointForm();$('#addCoupling').onclick=()=>couplingForm();$('#motionExample').onclick=()=>run(()=>{addExample();$('#modal').close();});$$('[data-joint-edit]').forEach(b=>b.onclick=()=>jointForm(P().joints.find(j=>j.id===b.dataset.jointEdit)));$$('[data-joint-control]').forEach(b=>b.onclick=()=>{$('#modal').close();dock(b.dataset.jointControl);});$$('[data-joint-delete]').forEach(b=>b.onclick=()=>run(()=>{api.commit(()=>{P().joints=P().joints.filter(j=>j.id!==b.dataset.jointDelete);P().couplings=P().couplings.filter(c=>c.driver!==b.dataset.jointDelete&&c.follower!==b.dataset.jointDelete);});motionDialog();}));$$('[data-coupling-edit]').forEach(b=>b.onclick=()=>couplingForm(P().couplings.find(c=>c.id===b.dataset.couplingEdit)));$$('[data-coupling-delete]').forEach(b=>b.onclick=()=>{api.commit(()=>P().couplings=P().couplings.filter(c=>c.id!==b.dataset.couplingDelete));motionDialog();});
 }
 const dockNode=document.createElement('section');dockNode.id='motionDock';dockNode.className='motion-dock';dockNode.hidden=true;dockNode.setAttribute('aria-label','Motion controls');$('#viewport').append(dockNode);
 function dock(id){stop();const j=P().joints.find(j=>j.id===id);if(!j)return;dockNode.hidden=false;const follower=P().couplings.some(c=>c.follower===id),axes=jointAxes(j.type),values=coupledValues(P()).get(id);dockNode.innerHTML=`<div class="motion-head"><strong>${esc(j.name)}</strong><button id="motionClose" aria-label="Close motion controls">×</button></div>${follower?'<p>Linked follower. Control its driver to move it.</p>':''}${axes.map((label,i)=>`<label>${esc(label)}<div class="motion-axis"><input type="range" data-motion-axis="${i}" aria-label="${esc(label)}" min="${j.limits[i].min}" max="${j.limits[i].max}" step="any" value="${values[i]}"${follower?' disabled':''}><input type="number" data-motion-value="${i}" aria-label="Exact ${esc(label)}" min="${j.limits[i].min}" max="${j.limits[i].max}" step="any" value="${+values[i].toFixed(3)}"${follower?' disabled':''}></div></label>`).join('')}<div class="mini-actions"><button id="motionPlay"${!axes.length||follower?' disabled':''}>Play</button><button id="motionSave"${!axes.length||follower?' disabled':''}>Keep pose</button><button id="motionReset">Reset preview</button><button id="motionEdit">Edit</button></div><p id="motionStatus" class="fine" role="status">Preview · Keep pose saves to the project.</p>`;
  const update=(index,n)=>{const q=preview[id]?[...preview[id]]:[...j.values];q[index]=n;const next={[id]:q};coupledValues(P(),next);S()?.applyPose?.(next);preview=next;for(let i=0;i<axes.length;i++){const value=q[i];$(`[data-motion-axis="${i}"]`).value=value;$(`[data-motion-value="${i}"]`).value=+value.toFixed(3);}$('#motionStatus').textContent='Preview · Keep pose saves to the project.';};
  $$('[data-motion-axis]').forEach(el=>el.oninput=()=>{stop(false);run(()=>update(+el.dataset.motionAxis,+el.value));});$$('[data-motion-value]').forEach(el=>el.onchange=()=>{stop(false);run(()=>{if(!el.value.trim())throw Error('Enter a motion value.');update(+el.dataset.motionValue,+el.value);});});
  $('#motionPlay').onclick=()=>{if(playing){stop(false);return;}if(!S())return notify('Motion playback requires the 3D view.');if(S().explode)return notify('Return Explode to 0% to preview motion.');playing=true;$('#motionPlay').textContent='Pause';let lastPaint=0;const start=performance.now(),initial=preview[id]?.[0]??j.values[0],range=j.limits[0].max-j.limits[0].min,offset=(initial-j.limits[0].min)/range;const tick=now=>{if(!playing)return;if(now-lastPaint<32){frame=requestAnimationFrame(tick);return;}lastPaint=now;const t=(offset+(now-start)/4000)%2,q=j.limits[0].min+(t<=1?t:2-t)*range;try{update(0,q);}catch(e){stop(false);$('#motionStatus').textContent=e.message;return;}frame=requestAnimationFrame(tick);};frame=requestAnimationFrame(tick);};
  $('#motionSave').onclick=()=>run(()=>{const value=preview[id]?[...preview[id]]:[...j.values];stop(false);api.commit(()=>P().joints.find(a=>a.id===id).values=value);dock(id);notify('Joint pose saved.');});$('#motionReset').onclick=()=>dock(id);$('#motionClose').onclick=()=>{stop();dockNode.hidden=true;};$('#motionEdit').onclick=()=>jointForm(j);
 }
 function addExample(){const gear=makePart('mech-pinion',{name:'Example pinion',pos:[-30,0,35],dims:[22,22,10]}),rack=makePart('mech-rack',{name:'Example rack',pos:[-30,15,35],dims:[100,10,10],rot:[90,0,0]}),j=createJoint({...P(),parts:[...P().parts,gear,rack]},{name:'Pinion rotation',child:gear.id,limits:[{min:-180,max:180},{min:-90,max:90},{min:-90,max:90}]}),s=createJoint({...P(),parts:[...P().parts,gear,rack]},{name:'Rack travel',type:'slider',child:rack.id,axis:[1,0,0],limits:[{min:-40,max:40},{min:-90,max:90},{min:-90,max:90}]});api.commit(()=>{P().parts.push(gear,rack);P().joints.push(j,s);P().couplings.push({id:uid(),name:'Example rack drive',type:'rack',driver:j.id,follower:s.id,ratio:-1,pitchDiameter:20,offset:0});});S()?.fit();dock(j.id);}
 async function loadLibrary(){try{harnessLibrary=(await readRecord('harness-library')||[]).map(normalizeHarnessTemplate);}catch(e){notify('Harness library could not be read: '+e.message);}}loadLibrary();
 function harnessDialog(){stop();const templates=[...new Map([...harnessLibrary,...P().harnessLibrary].map(t=>[t.id,t])).values()];openModal('Wiring harnesses',`<p>Group cable routes into reusable harnesses. Edit each branch’s path, sleeve, connectors, conductor colors, gauge and pin labels.</p><div class="modal-actions"><button id="newHarness" class="primary">Create harness</button><button id="looseCable">Add cable route</button><button id="harnessCSV">Export cut list CSV</button></div>${P().harnesses.map(h=>`<section class="harness-card"><div class="motion-head"><strong>${esc(h.name)}</strong><button data-harness-edit="${esc(h.id)}">Edit / routes</button></div><p class="fine">${esc(h.notes)}</p>${P().wires.filter(w=>w.harnessId===h.id).map(w=>`<div class="feature-row"><button data-harness-wire="${esc(w.id)}">${esc(w.name)}<small>${w.conductors?.length||0} conductors · ${routeLength(evaluatePose(P()),w).toFixed(1)} mm incl. allowances · ${esc(w.sleeve||'none')}</small></button><button data-harness-conductors="${esc(w.id)}">Conductors</button></div>`).join('')}<div class="mini-actions"><button data-harness-add="${esc(h.id)}">Add branch</button><button data-harness-save="${esc(h.id)}">Save reusable</button><button data-harness-delete="${esc(h.id)}">Ungroup routes</button></div></section>`).join('')}<h3>Unassigned routes</h3>${P().wires.filter(w=>!w.harnessId).map(w=>`<div class="feature-row"><button data-harness-wire="${esc(w.id)}">${esc(w.name)}</button><button data-harness-conductors="${esc(w.id)}">Conductors</button></div>`).join('')}<h3>Reusable harness library</h3>${templates.length?templates.map(t=>`<div class="feature-row"><span>${esc(t.name)}<small>${t.routes.length} routes · ${t.ports.length} attachment roles</small></span><button data-harness-insert="${esc(t.id)}">Insert</button><button data-harness-template-delete="${esc(t.id)}">×</button></div>`).join(''):'<p class="muted">Save a harness to reuse its branches, pin mapping and routing in another project.</p>'}<p class="fine">Cut lengths use straight route segments at the saved joint pose plus entered slack and service length. Unsaved motion previews are excluded. These are layout estimates; verify bend radius and installation length on your hardware.</p>`);
  $('#newHarness').onclick=()=>harnessForm();$('#looseCable').onclick=()=>api.openCable();$('#harnessCSV').onclick=()=>download(new Blob(['\ufeff'+harnessCSV(evaluatePose(P()))],{type:'text/csv;charset=utf-8'}),'mockupbench-harness-cut-list.csv');$$('[data-harness-edit]').forEach(b=>b.onclick=()=>harnessForm(P().harnesses.find(h=>h.id===b.dataset.harnessEdit)));$$('[data-harness-wire]').forEach(b=>b.onclick=()=>api.openCable(P().wires.find(w=>w.id===b.dataset.harnessWire)));$$('[data-harness-conductors]').forEach(b=>b.onclick=()=>conductorForm(P().wires.find(w=>w.id===b.dataset.harnessConductors)));$$('[data-harness-add]').forEach(b=>b.onclick=()=>api.openCable(null,b.dataset.harnessAdd));$$('[data-harness-delete]').forEach(b=>b.onclick=()=>{api.commit(()=>{P().harnesses=P().harnesses.filter(h=>h.id!==b.dataset.harnessDelete);for(const w of P().wires)if(w.harnessId===b.dataset.harnessDelete)w.harnessId='';});harnessDialog();});
  $$('[data-harness-save]').forEach(b=>b.onclick=async()=>{try{const t=captureHarness(P(),b.dataset.harnessSave);if(templates.length>=50)throw Error('Maximum 50 reusable harnesses.');api.commit(()=>P().harnessLibrary.push(t));harnessLibrary=[...harnessLibrary,t];await saveRecord('harness-library',harnessLibrary);harnessDialog();notify('Harness saved to this project and the reusable library.');}catch(e){notify(e.message);}});$$('[data-harness-insert]').forEach(b=>b.onclick=()=>insertHarnessForm(templates.find(t=>t.id===b.dataset.harnessInsert)));$$('[data-harness-template-delete]').forEach(b=>b.onclick=async()=>{try{const next=harnessLibrary.filter(t=>t.id!==b.dataset.harnessTemplateDelete);await saveRecord('harness-library',next);harnessLibrary=next;api.commit(()=>P().harnessLibrary=P().harnessLibrary.filter(t=>t.id!==b.dataset.harnessTemplateDelete));harnessDialog();}catch(e){notify(e.message);}});
 }
 function harnessForm(existing){const h=existing||{id:uid(),name:'Wiring harness',notes:''};form(existing?'Edit harness':'Create harness',`${input('Harness name','harnessName',h.name)}<label>Notes<textarea name="harnessNotes">${esc(h.notes)}</textarea></label><h3>Include routes</h3>${P().wires.map(w=>`<label class="check"><input type="checkbox" data-route-check="${esc(w.id)}"${w.harnessId===h.id?' checked':''}>${esc(w.name)}${w.harnessId&&w.harnessId!==h.id?' · moves from another harness':''}</label>`).join('')||'<p>You can add branches after creating this harness.</p>'}`,()=>{api.commit(()=>{P().harnesses=P().harnesses.filter(a=>a.id!==h.id);P().harnesses.push({...h,name:get('harnessName'),notes:get('harnessNotes')});const ids=new Set($$('[data-route-check]').filter(el=>el.checked).map(el=>el.dataset.routeCheck));for(const w of P().wires)if(ids.has(w.id))w.harnessId=h.id;else if(w.harnessId===h.id)w.harnessId='';});harnessDialog();return false;});}
 function conductorForm(w){const conductors=structuredClone(w.conductors||[]);form('Harness branch · '+w.name,`${choose('Harness','harnessId',[['','Unassigned'],...P().harnesses.map(h=>[h.id,h.name])],w.harnessId||'')}<div class="fields two">${input('Start connector','startConnector',w.startConnector||'')}${input('End connector','endConnector',w.endConnector||'')}${choose('Sleeve','sleeve',['none','braid','loom','ribbon'].map(x=>[x,x]),w.sleeve||'none')}${input('Additional service length (mm)','extraLength',w.extraLength||0,'number')}</div><h3>Conductors</h3><div id="conductorRows"></div><button type="button" id="addConductor">＋ Add conductor</button><p class="fine">Gauge accepts AWG or area, e.g. 22 AWG or 0.5 mm². Pin names are labels; ratings and connectivity need independent verification.</p>`,()=>{collect();api.commit(()=>{Object.assign(w,{harnessId:get('harnessId'),startConnector:get('startConnector'),endConnector:get('endConnector'),sleeve:get('sleeve'),extraLength:val('extraLength'),conductors});});});
  function collect(){for(const row of $$('[data-conductor]')){const c=conductors[+row.dataset.conductor];for(const el of row.querySelectorAll('[data-c-field]'))c[el.dataset.cField]=el.value;}}
  function rows(){$('#conductorRows').innerHTML=conductors.map((c,i)=>`<div class="conductor-row" data-conductor="${i}"><strong>Wire ${i+1}</strong><div class="fields two">${[['label','Label'],['gauge','Gauge / area'],['signal','Signal'],['startPin','From pin'],['endPin','To pin'],['color','Color']].map(([k,l])=>`<label>${l}<input data-c-field="${k}" aria-label="Wire ${i+1} ${l}" type="${k==='color'?'color':'text'}" value="${esc(c[k]||'')}"></label>`).join('')}</div><button type="button" data-remove-conductor="${i}">Remove wire</button></div>`).join('');$$('[data-remove-conductor]').forEach(b=>b.onclick=()=>{collect();conductors.splice(+b.dataset.removeConductor,1);rows();});}
  rows();$('#addConductor').onclick=()=>{if(conductors.length>=64)return notify('Maximum 64 conductors per branch.');collect();conductors.push({id:uid(),label:'Wire '+(conductors.length+1),gauge:'22 AWG',signal:'',startPin:'',endPin:'',color:['#d64838','#252525','#e6c04b','#417eac','#eeeeee','#4c9467'][conductors.length%6]});rows();};
 }
 function insertHarnessForm(t){form('Insert reusable harness',`${input('Instance name','instanceName',t.name)}${triplet('Unattached route origin (mm)','origin',[0,0,20])}<h3>Connect attachment roles</h3>${t.ports.map((port,i)=>choose(port.name,'port'+i,[['','Leave unattached'],...P().parts.flatMap(p=>[[p.id,p.name+' / saved local position'],...p.anchors.map(a=>[p.id+'|'+a.id,p.name+' / '+a.name])])],'')).join('')}<p class="fine">Unattached waypoints retain their saved offsets. Attached points follow the selected part or reference point. Edit the route after insertion to suit the new assembly.</p>`,()=>api.commit(()=>{const bindings=Object.fromEntries(t.ports.map((p,i)=>[p.id,get('port'+i)]));const h=insertHarness(P(),t,bindings,coords('origin'));h.name=get('instanceName');}));}
 function cutoutPattern(part){const d=interfaceDefinitions.find(d=>d.id===part.interfaceId);if(!d)return;const list=panels(P().enclosure);form('InterfaceBench mounting pattern',`${choose('Target enclosure panel','panel',list.map(p=>[p.id,p.name]),'@Lid')}${choose('Panel face','face',['top','bottom','front','back','left','right'].map(x=>[x,x]),'top')}<div class="fields">${input('Pattern center U (mm)','u',0,'number')}${input('Pattern center V (mm)','v',0,'number')}${input('Rotation (°)','patternAngle',0,'number')}</div><p>${d.openings.length} nominal openings from ${esc(d.name)}. Pattern dimensions retain the original InterfaceBench definition even if you resize the 3D component. Verify the selected hardware drawing before fabrication.</p>`,()=>{const angle=val('patternAngle')*Math.PI/180,u=val('u'),v=val('v');const fs=d.openings.map((s,i)=>{if(!['circle','rect'].includes(s.type))throw Error('This source pattern requires a custom profile.');const x=s.x||0,y=s.y||0;return normalizeFeature({...featureDefaults(),id:uid(),host:get('panel'),linkedPart:part.id,name:part.name+' opening '+(i+1),face:get('face'),shape:s.type==='circle'?'ellipse':s.r?'roundrect':'rectangle',u:u+x*Math.cos(angle)-y*Math.sin(angle),v:v+x*Math.sin(angle)+y*Math.cos(angle),w:s.type==='circle'?s.d:s.w,h:s.type==='circle'?s.d:s.h,radius:s.r||0,angle:val('patternAngle')});});api.commit(()=>P().features.push(...fs));});}
 function inspectorHTML(id){const p=P().parts.find(p=>p.id===id),joints=P().joints.filter(j=>j.child===id||j.parent===id);let html=`<section class="inspector-section"><h3>Motion</h3><button data-engineering="motion">Joints & motion${joints.length?' · '+joints.length:''}</button>${driven(P(),id)?'<p class="hint">Position is controlled by a joint. Use its motion controls or remove the joint to reposition the body.</p>':''}</section>`;if(p?.kind==='mechanism'){html+=`<section class="inspector-section"><h3>Component geometry</h3>${Object.entries(p.params).filter(([k])=>k!=='shape').map(([k,v])=>`<label>${esc(k==='bore'?'Bore / outside diameter ratio':k)}<input type="number" data-component-param="${k}" min="${k==='bore'?.01:3}" max="${k==='bore'?.8:128}" step="${k==='bore'?.01:1}" value="${v}"></label>`).join('')}<p class="fine">Illustrative geometry. Gear teeth are not manufacturing profiles.</p></section>`;}if(p?.interfaceId){const d=interfaceDefinitions.find(d=>d.id===p.interfaceId);html+=`<section class="inspector-section"><h3>InterfaceBench component</h3><button data-engineering="pattern">Add nominal cutout pattern</button><details><summary>${d.terminals.length} terminal labels · source notes</summary><p>${d.terminals.map(t=>esc(t.name)).join(' · ')||'No electrical terminals'}</p><p>${esc(d.notes)}</p><p>${esc(d.source)}</p><p class="fine">3D geometry and rear terminal positions are illustrative layout models. Original source dimensions and verification notes are preserved in the bundled catalog.</p></details></section>`;}return html;}
 document.addEventListener('click',e=>{const action=e.target.closest('[data-engineering]')?.dataset.engineering;if(!action)return;run(()=>{if(action==='motion')motionDialog();if(action==='harness')harnessDialog();if(action==='pattern')cutoutPattern(P().parts.find(p=>p.id===api.selected()));});});document.addEventListener('change',e=>{const key=e.target.dataset.componentParam;if(!key)return;run(()=>api.commit(()=>{const p=P().parts.find(p=>p.id===api.selected());p.params[key]=+e.target.value;}));});
 const button=document.createElement('button');button.dataset.engineering='motion';button.textContent='Joints & motion';$('#assembleMenu').append(button);
 return {inspectorHTML,motionDialog,harnessDialog,dock,reset(){stop();dockNode.hidden=true;},beforeRefresh(){stop(false);preview={};dockNode.hidden=true;},reportExtras(){return `<h2>Motion</h2><ul>${P().joints.map(j=>`<li>${esc(j.name)} · ${esc(JOINT_TYPES[j.type])} · ${j.values.join(', ')}</li>`).join('')}</ul><h2>Harnesses</h2><ul>${P().harnesses.map(h=>`<li>${esc(h.name)} · ${P().wires.filter(w=>w.harnessId===h.id).length} routes</li>`).join('')}</ul>`;}};
}
